[{"order":1,"type":"heading","text":"Integrating TypeScript with Express.js"},{"order":2,"type":"paragraph","text":"This tutorial guides you through setting up a robust Node.js application using Express.js and TypeScript. TypeScript adds static typing to JavaScript, improving code maintainability and reducing runtime errors."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Node.js and npm installed on your system."},{"order":5,"type":"bullet_point","text":"Basic understanding of JavaScript and TypeScript."},{"order":6,"type":"subheading","text":"Setting up the Project"},{"order":7,"type":"paragraph","text":"First, create a new directory for your project and navigate into it."},{"order":8,"type":"code","text":"mkdir express-typescript
cd express-typescript"},{"order":9,"type":"paragraph","text":"Initialize a new Node.js project."},{"order":10,"type":"code","text":"npm init -y"},{"order":11,"type":"paragraph","text":"Install Express.js, TypeScript, and related typings."},{"order":12,"type":"code","text":"npm install express
npm install --save-dev typescript @types/node @types/express"},{"order":13,"type":"subheading","text":"Configuring TypeScript"},{"order":14,"type":"paragraph","text":"Create a 'tsconfig.json' file in the root of your project to configure the TypeScript compiler."},{"order":15,"type":"code","text":"tsc --init"},{"order":16,"type":"paragraph","text":"Modify the 'tsconfig.json' file to suit your project's needs. A sample configuration is shown below:"},{"order":17,"type":"code","text":"{
  "compilerOptions": {
    "target": "es6",
    "module": "commonjs",
    "outDir": "./dist",
    "rootDir": "./src",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "forceConsistentCasingInFileNames": true
  }
}"},{"order":18,"type":"subheading","text":"Creating the Express Application"},{"order":19,"type":"paragraph","text":"Create a 'src' directory and add an 'index.ts' file inside it. This will be the entry point of your application."},{"order":20,"type":"code","text":"mkdir src
touch src/index.ts"},{"order":21,"type":"paragraph","text":"Add the following code to 'src/index.ts':"},{"order":22,"type":"code","text":"import express, { Request, Response } from 'express';

const app = express();
const port = 3000;

app.get('/', (req: Request, res: Response) => {
  res.send('Hello, World with TypeScript!');
});

app.listen(port, () => {
  console.log(`Server running at http://localhost:${port}`);
});"},{"order":23,"type":"subheading","text":"Building and Running the Application"},{"order":24,"type":"paragraph","text":"Compile the TypeScript code to JavaScript using the TypeScript compiler."},{"order":25,"type":"code","text":"tsc"},{"order":26,"type":"paragraph","text":"Run the compiled JavaScript file using Node.js."},{"order":27,"type":"code","text":"node dist/index.js"},{"order":28,"type":"paragraph","text":"You should see the message "Server running at http://localhost:3000" in your console. Open your browser and navigate to that address to see the "Hello, World with TypeScript!" message."},{"order":29,"type":"subheading","text":"Adding a Build Script"},{"order":30,"type":"paragraph","text":"Add a build script to your 'package.json' file for easier compilation."},{"order":31,"type":"code","text":"{
  "name": "express-typescript",
  "version": "1.0.0",
  "description": "",
  "main": "index.js",
  "scripts": {
    "build": "tsc",
    "start": "node dist/index.js",
    "dev": "npm run build && npm start"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "express": "^4.17.1"
  },
  "devDependencies": {
    "@types/express": "^4.17.11",
    "@types/node": "^14.14.31",
    "typescript": "^4.1.5"
  }
}"},{"order":32,"type":"paragraph","text":"Now you can use 'npm run build' to compile the TypeScript code and 'npm start' to run the application. 'npm run dev' will build and start the application."},{"order":33,"type":"subheading","text":"Conclusion"},{"order":34,"type":"paragraph","text":"You have successfully integrated TypeScript with Express.js. This setup provides a solid foundation for building scalable and maintainable Node.js applications."}]
